import {
  canonical,
  object,
  resolve,
  type SchemaEntry,
  type Snapshot,
  type ToolEntry,
} from "./model.ts";
import { jsonValidator, seededRandom, validExample, variants } from "./examples.ts";

const notice =
  "Generated by `bun run docs:protocol`. Edit source schemas, then regenerate.\n\nJSON Schema validates structure. `x-ace-constraint` names additional semantic rules that clients must enforce; Zod remains the full validator.\n";
const families = [
  {
    file: "commands",
    title: "Commands",
    names: ["Command", "CommandPayload", "CommandResult"],
    intro:
      "Send commands inside the client `command` envelope. Retry with the same command id for idempotency. The daemon replies with `commandResult`, whose commandId correlates with the request. `ok: false` and `error` describe rejection; acceptance does not mean the whole agent tree has finished.",
  },
  {
    file: "requests",
    title: "Client requests",
    names: ["ClientMessage"],
    intro:
      "Authenticate with `hello` and the negotiated protocolVersion before subscribing or issuing commands. Use exactly one credential, token or ticket; the examples use dummy values. Subscribe with afterSeq to resume a cursor; unsubscribe releases the subscription. Notification and presence requests obey the authenticated device's scopes.",
  },
  {
    file: "push",
    title: "Server results and push messages",
    names: ["ServerMessage", "DeliveryEvent"],
    intro:
      "`welcome` establishes protocolVersion and headSeq. Snapshot seq must match view.seq. Events and progress advance coverage even for filtered subscriptions. `firstSeq` describes coalesced delta coverage. Persist throughSeq only after applying a batch. Errors include a code and message; `pong` answers `ping`. Notifications grant no approval authority.",
  },
  {
    file: "events",
    title: "Canonical events",
    names: ["Event", "EventPayload"],
    intro:
      "See [ADR 0004](../adr/0004-canonical-agent-model.md). Events are canonical facts, not raw provider frames. Host seq increases across the append-only log. Thread status comes from the whole agent tree: do not infer done from run.ended. Concatenate item.delta; item.updated is authoritative. Items can arrive after their run ends.",
  },
];
function text(value: unknown): string {
  return String(value).replaceAll("|", "\\|").replaceAll("\n", " ");
}
function typeLabel(schema: Record<string, unknown>): string {
  if (typeof schema.$ref === "string")
    return `[${schema.$ref.split("/").at(-1)}](schema/${schema.$ref.split("/").at(-1)})`;
  if (Object.hasOwn(schema, "const")) return `\`${JSON.stringify(schema.const)}\``;
  if (schema.enum) return text(JSON.stringify(schema.enum));
  if (schema.anyOf || schema.oneOf) return "union";
  if (schema.allOf) return "intersection";
  return text(schema.type ?? "any JSON value");
}
export function renderReference(
  entries: SchemaEntry[],
  tools: ToolEntry[],
  snapshot: Snapshot,
): Map<string, string> {
  const files = new Map<string, string>();
  const validator = jsonValidator(snapshot);
  const random = seededRandom(42);
  function section(entry: SchemaEntry): string {
    const schema = snapshot.schemas[entry.name];
    if (!Object.hasOwn(snapshot.schemas, entry.name) || !schema)
      throw new Error(`Missing schema ${entry.name}`);
    let result = `## ${entry.name}\n\n[JSON Schema](schema/${entry.name}.json), ${entry.io ?? "input"} validation.\n`;
    if (entry.schema.meta()?.["x-ace-transport"] === "binary")
      return (
        result +
        "\nBinary transport: native Uint8Array bytes. No JSON value is accepted; the JSON Schema rejects all JSON.\n"
      );
    for (const [index, variant] of variants(schema, snapshot).entries()) {
      const node = resolve(variant, snapshot.schemas);
      const properties = object(node.properties);
      const tag = object(properties.type).const ?? object(properties.kind).const;
      if (variants(schema, snapshot).length > 1)
        result += `\n### ${tag ?? `Variant ${index + 1}`}\n`;
      if (node["x-ace-constraint"]) result += `\nSemantic rule: ${node["x-ace-constraint"]}\n`;
      if (Object.keys(properties).length) {
        result += "\n| Field | Required | Type | Constraints |\n| --- | --- | --- | --- |\n";
        for (const [key, value] of Object.entries(properties)) {
          const field = object(value);
          const constraints = Object.fromEntries(
            Object.entries(field).filter(
              ([attribute]) => !["type", "$ref", "enum", "const"].includes(attribute),
            ),
          );
          result += `| ${key} | ${node.required?.includes(key) ? "yes" : "no"} | ${typeLabel(field)} | ${Object.keys(constraints).length ? text(JSON.stringify(constraints)) : ""} |\n`;
        }
      } else result += `\nType: ${typeLabel(node)}. See JSON Schema for constraints.\n`;
      const example = validExample(entry.name, entry.schema, variant, snapshot, random, validator);
      result += `\nExample:\n\n\`\`\`json\n${canonical(example).trimEnd()}\n\`\`\`\n`;
    }
    return result;
  }
  const orchestration = {
    file: "orchestration",
    title: "Orchestration",
    names: entries
      .filter((entry) => /^(Orchestration|Lane|SpawnAgentRequest|TestResults)/.test(entry.name))
      .map((entry) => entry.name),
    intro:
      "See [ADR 0013](../adr/0013-orchestration.md). Orchestration commands use the authenticated command envelope. The event, fact, intent and snapshot contracts below are exported for engine integration; they do not imply an implemented WebSocket subscription. A lane succeeds only after the whole thread tree settles and its checks pass.",
  };
  const models = {
    file: "models",
    title: "Model catalog",
    names: entries
      .filter((entry) => /^(Model|CatalogModel)/.test(entry.name))
      .map((entry) => entry.name),
    intro:
      "See [ADR 0036](../adr/0036-model-catalog.md). Model queries are correlated by requestId and answered with models.result. They query local provider metadata without running inference. Listings may be stale; explicit refresh requires operate scope, while list and resolve require read scope. Model ids and capabilities belong to the reported provider instance.",
  };
  const automations = {
    file: "automations",
    title: "Automations",
    names: entries
      .filter((entry) => /^(Automation|TriggerVariables)/.test(entry.name))
      .map((entry) => entry.name),
    intro:
      "See [ADR 0015](../adr/0015-automations.md). Schedule and trigger contracts belong to the local automation service. Their request and response envelopes are exported separately from the current daemon wire union; clients must use an implemented authenticated route before sending them.",
  };
  const forge = {
    file: "forge",
    title: "Forge",
    names: entries.filter((entry) => entry.name.startsWith("Forge")).map((entry) => entry.name),
    intro:
      "See [ADR 0016](../adr/0016-forge.md). These contracts come from the public @ace/protocol/forge entry point. Commands, events and PR summaries are service integration contracts; they do not add variants to the daemon's current WebSocket union. Forge facts do not determine agent completion.",
  };
  const pages = [...families, orchestration, models, automations, forge];
  const assigned = new Set(pages.flatMap((family) => family.names));
  for (const family of pages) {
    files.set(
      `${family.file}.md`,
      `# ${family.title}\n\n${notice}\n${family.intro}\n\n` +
        entries
          .filter((entry) => family.names.includes(entry.name))
          .map(section)
          .join("\n"),
    );
  }
  let mcp = `# MCP tools\n\n${notice}\nBuilt-in definitions come from \`@ace/mcp-server\`. The local /mcp endpoint uses session-scoped credentials and capability filtering. Discovery exposes only registered tools allowed for that session. Dynamic browser/preview toolkits depend on installed host adapters and are not fabricated here. Inputs use input validation; structured results use output validation, including populated defaults. Standard MCP call failures use isError and text content.\n`;
  for (const tool of tools) {
    mcp += `\n## ${tool.name}\n\n${tool.description}\n\nRequired capability: ${tool.capability ?? "none beyond session authentication"}. Timeout: ${tool.timeoutMs} ms.\n`;
    for (const name of [tool.input, tool.output]) {
      assigned.add(name);
      const entry = entries.find((item) => item.name === name);
      if (!entry) throw new Error(`Missing tool schema ${name}`);
      mcp += "\n" + section(entry);
    }
  }
  files.set("mcp.md", mcp);
  files.set(
    "types.md",
    `# Supporting types\n\n${notice}\n` +
      entries
        .filter((entry) => !assigned.has(entry.name))
        .map(section)
        .join("\n"),
  );
  files.set(
    "README.md",
    `# Daemon protocol reference\n\n${notice}\nProtocol version: **${snapshot.protocolVersion}**. Exchange UTF-8 JSON objects over the daemon WebSocket. This describes schemas accepted on the wire, so defaulted fields may be omitted. MCP result schemas describe populated outputs.\n\n- [Commands, requests, results and errors](commands.md)\n- [Client requests](requests.md)\n- [Server results and push messages](push.md)\n- [Canonical events](events.md)\n- [MCP tools](mcp.md)\n- [Orchestration](orchestration.md)\n- [Model catalog](models.md)\n- [Automations](automations.md)\n- [Forge](forge.md)\n- [Supporting types](types.md)\n\n## Version and compatibility\n\nClients negotiate protocolVersion in hello/welcome. Version ${snapshot.protocolVersion} permits additive optional fields, wider types and new messages when readers tolerate unknown fields and message variants. Never infer whole-tree completion from provider turn completion. Removing or renaming fields, narrowing types or adding required fields breaks existing clients and requires a new negotiated version. JSON Schema ids use the versioned namespace https://ace.local/protocol/v${snapshot.protocolVersion}/; these are identifiers, not network endpoints. Resolve them through the local schema directory.\n\nRelease tooling captures a baseline with \`bun run docs:protocol:snapshot --output release.json\` and compares it using \`bun run docs:protocol:compat --baseline release.json\`. Commit each released snapshot with its release artifacts. No release has been declared by this generator. Compatibility checks conservatively reject unfamiliar validation changes and changed semantic constraints.\n\n## Example\n\n\`\`\`json\n{"type":"ping"}\n\`\`\`\n\nExamples on every page are synthetic and checked against Zod and exported JSON Schema at generation time. Replace example credentials and ids with your own authenticated values. Regenerate with \`bun run docs:protocol\`; \`bun run docs:protocol --check\` detects stale, missing and unexpected output.\n`,
  );
  const ping = entries.find((entry) => entry.name === "ClientMessage");
  if (
    ping &&
    (!ping.schema.safeParse({ type: "ping" }).success ||
      !validator.getSchema(snapshot.schemas.ClientMessage?.$id ?? "")?.({ type: "ping" }))
  )
    throw new Error("Index example no longer valid: ClientMessage ping");
  for (const [name, schema] of Object.entries(snapshot.schemas))
    files.set(`schema/${name}.json`, canonical(schema));
  return files;
}
